const test=require('node:test');
const assert=require('node:assert/strict');
const {expiresAt}=require('../cache/service.cjs');
test('seconds, restrictive precedence and duplicates',()=>{
  assert.equal(expiresAt('public, MAX-AGE = "12"',500),12500);
  assert.equal(expiresAt(['max-age=30','max-age=7'],500),7500);
  assert.equal(expiresAt('max-age=0',500),500);
  assert.equal(expiresAt(['max-age=12','No-Store'],500),null);
  assert.equal(expiresAt('PRIVATE, max-age=100',500),null);
  assert.equal(expiresAt('s-maxage=100',500),null);
  const input=['max-age=8','max-age=6'];
  assert.equal(expiresAt(input,0),6000);
  assert.deepEqual(input,['max-age=8','max-age=6']);
});
test('strict values and safe arithmetic',()=>{
  for(const value of ['-1','1.5','12junk','+3','"3x"','']) assert.equal(expiresAt('max-age='+value,0),null);
  assert.equal(expiresAt('max-age=bad, max-age=4',0),4000);
  assert.throws(()=>expiresAt('max-age=9007199254740992',0),RangeError);
  assert.throws(()=>expiresAt('max-age=1',Number.MAX_SAFE_INTEGER),RangeError);
  assert.equal(expiresAt('max-age=999999999999999999999, max-age=2',0),2000);
});

