exports.lifetime=function(parts) {
  if(parts.some(([key])=>key==='private'||key==='no-store')) return null;
  const ages=[];
  for(const [key,value] of parts) {
    if(key!=='max-age'||value===null) continue;
    const match=/^(?:([0-9]+)|"([0-9]+)")$/.exec(value);
    if(match && match[0]===value) ages.push(BigInt(match[1]??match[2]));
  }
  if(!ages.length) return null;
  return ages.reduce((a,b)=>a<b?a:b);
};

