const {parse}=require('./directives.cjs');
const {lifetime}=require('./policy.cjs');
exports.expiresAt=(header,storedAtMs)=>{
  const ttl=lifetime(parse(header));
  if(ttl===null) return null;
  const expiry=BigInt(storedAtMs)+ttl*1000n;
  if(ttl>BigInt(Number.MAX_SAFE_INTEGER)||expiry>BigInt(Number.MAX_SAFE_INTEGER)) throw new RangeError('unsafe cache expiry');
  return Number(expiry);
};

